    gal: {n:"Ростиславичи галицкие", up:"rur", c:"#a8c75a", d:"потомки Ростислава Владимировича, внука Ярослава; Галич и Перемышль"},
    oth: {n:"Не Рюриковичи", c:"#a89a7e"},
